import random
import networkx as nx

def calculate_sum_labels(G):
    degrees = dict(G.degree())
    s = 0
    for u, v in G.edges():
        s += abs(degrees[u] - degrees[v])
    return s

def solve_for_n(n, iterations=10000):
    # Random starting graph
    G = nx.gnp_random_graph(n, 0.5)
    current_s = calculate_sum_labels(G)

    best_s = current_s

    for i in range(iterations):
        u = random.randint(0, n - 1)
        v = random.randint(0, n - 1)
        if u == v:
            continue

        # Flip edge (u, v)
        if G.has_edge(u, v):
            G.remove_edge(u, v)
            new_s = calculate_sum_labels(G)
            if new_s >= current_s:
                current_s = new_s
                if current_s > best_s:
                    best_s = current_s
            else:
                G.add_edge(u, v)
        else:
            G.add_edge(u, v)
            new_s = calculate_sum_labels(G)
            if new_s >= current_s:
                current_s = new_s
                if current_s > best_s:
                    best_s = current_s
            else:
                G.remove_edge(u, v)

    return best_s

n = 11
best_overall = 0
for _ in range(20):
    res = solve_for_n(n)
    if res > best_overall:
        best_overall = res
print(f"Best found for n=11: {best_overall}")

